using System;using System.IO;using System.Collections.Generic;
class QuestSelectFixturesFG {
 static void Save(string prefix,string suffix,byte[] b){using(FileStream f=new FileStream(prefix+suffix,FileMode.CreateNew,FileAccess.Write))f.Write(b,0,b.Length);}
 static int Main(string[] args){if(args.Length!=2)return 2;if(Directory.Exists(args[1]))throw new IOException("Fresh native select fixtures required");Directory.CreateDirectory(args[1]);Offline70QuestCatalogFG catalog=Offline70QuestCatalogFG.Load(args[0]);Offline70QuestEngineFG engine=new Offline70QuestEngineFG(catalog);byte[] keys=new byte[334];for(int i=0;i<334;i++)keys[i]=(byte)i;Offline70Role role=new Offline70Role{Id=1,Job=0,Name="yoyo",Level=1,CreatedUtc="2026-10-01T01:20:24.2661160Z"};
  foreach(int count in new int[]{0,1,20}){Offline70ProgressionStateFG s=new Offline70ProgressionStateFG();List<ushort> ids=new List<ushort>();foreach(Offline70QuestDefinitionFG q in catalog.Definitions.Values){if(!q.Supported)continue;if(s.Active.Count==count)break;int width=q.Type=="[hunt monster]"?q.Condition.Length/4:1;s.Active.Add(new Offline70QuestActiveFG{Id=q.Id,Progress=new int[width],Instance=Guid.NewGuid().ToString("N")});ids.Add(q.Id);}
   byte[] packet=Offline70RoleProtocol.BatchSelectFG(role,s,catalog,engine,keys,1),padded=Offline70SelectCipher.Crypt(Slice(packet,15),keys,false),body=new byte[150];Buffer.BlockCopy(padded,0,body,0,150);for(int i=0;i<count;i++)if(BitConverter.ToUInt16(body,22+6*i)!=ids[i]||BitConverter.ToUInt32(body,24+6*i)!=engine.WireRemaining(catalog.Get(ids[i]),s.Active[i],s))throw new InvalidDataException("Select active field position");for(int i=count;i<20;i++)if(BitConverter.ToUInt16(body,22+6*i)!=65535||BitConverter.ToUInt32(body,24+6*i)!=0)throw new InvalidDataException("Select unused slots");string prefix=Path.Combine(args[1],"select-"+count);Save(prefix,".keys.bin",keys);Save(prefix,".body.bin",body);Save(prefix,".reply.bin",packet);foreach(int n in new int[]{16,64}){byte[] v=new byte[n];for(int i=0;i<n;i++)v[i]=(byte)i;Save(prefix,".vector"+n+".bin",Offline70SelectCipher.Crypt(v,keys,true));}string text="[";for(int i=0;i<count;i++){if(i>0)text+=",";text+="["+ids[i]+","+engine.WireRemaining(catalog.Get(ids[i]),s.Active[i],s)+",0]";}File.WriteAllText(prefix+".expected.json",text+"]");}
  Console.WriteLine("PASS FG select active slots0/1/20 field offsets22/24, unusedFFFF and tutorial tail");return 0;
 }
 static byte[] Slice(byte[] b,int at){byte[] s=new byte[b.Length-at];Buffer.BlockCopy(b,at,s,0,s.Length);return s;}
}
